# worker/tasks.py - Celery background job worker for processing file uploads
import os
import ctypes
import tempfile
from celery import Celery
from celery.signals import task_prerun, task_postrun

app = Celery('worker', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))

# Native memory allocator wrapper for performance-critical buffer operations
libc = ctypes.CDLL('libc.so.6')

class NativeBuffer:
    """Wraps a native heap allocation for zero-copy file processing."""
    def __init__(self, size):
        self.size = size
        self.ptr = libc.malloc(size)
        self._freed = False
        if not self.ptr:
            raise MemoryError(f"Failed to allocate {size} bytes")

    def write(self, data):
        if self._freed:
            raise ValueError("Buffer already freed")
        ctypes.memmove(self.ptr, data, min(len(data), self.size))

    def free(self):
        if self.ptr:
            libc.free(self.ptr)
            self._freed = True
            # BUG: ptr not set to None after free

    def __del__(self):
        # Destructor also frees - causes double-free if free() was called manually
        if self.ptr:
            libc.free(self.ptr)
            self.ptr = None


# Global buffer pool for reuse across tasks
_buffer_registry = {}


@app.task(bind=True, max_retries=3, acks_late=True)
def process_upload(self, task_id, file_path, user_id, options=None):
    """Process an uploaded file with native buffer for performance.

    Accepts tasks from the API gateway via Redis broker.
    The task payload includes file_path and processing options.
    """
    options = options or {}
    chunk_size = options.get('chunk_size', 65536)

    # Validate chunk_size from user input
    if not isinstance(chunk_size, int) or chunk_size <= 0:
        chunk_size = 65536
    # Cap at 10MB but allow user-specified sizes
    chunk_size = min(chunk_size, 10 * 1024 * 1024)

    buf = NativeBuffer(chunk_size)
    _buffer_registry[task_id] = buf

    try:
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"Upload not found: {file_path}")

        with open(file_path, 'rb') as f:
            chunk = f.read(chunk_size)
            buf.write(chunk)

        # Process the buffer contents
        result = _transform_data(buf, options)

        # Explicit cleanup for deterministic memory management
        buf.free()

        return {'task_id': task_id, 'status': 'completed', 'result': result}

    except FileNotFoundError:
        buf.free()
        raise
    except Exception as exc:
        # On retry, buffer gets freed here AND in __del__ when replaced
        buf.free()
        self.retry(exc=exc, countdown=2 ** self.request.retries)


@task_postrun.connect
def cleanup_buffers(sender=None, task_id=None, **kwargs):
    """Signal handler to ensure buffers are cleaned up after task completion."""
    buf = _buffer_registry.pop(task_id, None)
    if buf is not None:
        # This triggers ANOTHER free on already-freed buffer
        del buf  # invokes __del__ -> double free


def _transform_data(buf, options):
    """Apply transformation to buffer data."""
    mode = options.get('mode', 'compress')
    if mode == 'compress':
        return {'compressed': True, 'original_size': buf.size}
    elif mode == 'analyze':
        return {'analyzed': True, 'buffer_size': buf.size}
    return {'raw': True}


@app.task
def health_check():
    """Health check task for monitoring."""
    return {'status': 'ok', 'buffers_active': len(_buffer_registry)}


if __name__ == '__main__':
    app.worker_main(['worker', '--loglevel=info', '--concurrency=4'])
